// Shared Tailwind design tokens for the booking flow, aligned with the rest of
// the migrated site (purple #854ec9, soft rounded cards, Plus Jakarta display
// font). The status/payment pill palette matches the Bookings & Enquiries list
// (profile-page/bookings-enquiries.tsx) so a booking looks the same wherever it
// appears. Buttons / inputs / spinner come from the shared tour-detail ui.ts.
import { StylesConfig } from "react-select";

// Card shell used by every booking side-panel section + the main columns.
export const cardCls =
  "tw-rounded-2xl tw-border tw-border-solid tw-border-[#ece9f1] tw-bg-white tw-shadow-[0_2px_14px_rgba(20,16,28,0.05)]";

// Centred section heading inside a card (replaces the old Bootstrap .card-title).
export const cardTitleCls =
  "tw-font-display tw-text-[15px] tw-font-bold tw-tracking-tight tw-text-[#14101c] tw-m-0";

// Larger page-level heading (replaces <h3>/<h1 class="h3">).
export const pageTitleCls =
  "tw-font-display tw-text-[clamp(20px,2.4vw,28px)] tw-font-bold tw-tracking-tight tw-text-[#14101c] tw-m-0";

// --- Status / payment pills ------------------------------------------------
const pillBase =
  "tw-inline-flex tw-items-center tw-rounded-full tw-px-2.5 tw-py-1 tw-text-[11px] tw-font-semibold tw-capitalize tw-whitespace-nowrap";

const green = "tw-bg-[#eafaf0] tw-text-[#1f8a4c]";
const amber = "tw-bg-[#fef6e7] tw-text-[#b7791f]";
const red = "tw-bg-[#fdecec] tw-text-[#b23838]";
const blue = "tw-bg-[#e8f1fd] tw-text-[#2563aa]";
const brand = "tw-bg-[#f4eefc] tw-text-[#6a3da4]";
const gray = "tw-bg-[#f0eef4] tw-text-[#6b6577]";

const statusColors: Record<string, string> = {
  pending: amber,
  open: blue,
  closed: gray,
  confirmed: green,
  completed: green,
  cancelled: red,
};

const paymentColors: Record<string, string> = {
  pending: amber,
  charged: blue,
  partial: blue,
  paid: green,
  failed: red,
  partially_refunded: amber,
  refunded: red,
};

const promoColors: Record<string, string> = {
  active: amber,
  used: green,
  expired: gray,
};

export const statusPillCls = (status?: string) =>
  `${pillBase} ${statusColors[(status || "").toLowerCase()] || gray}`;

export const paymentPillCls = (status?: string) =>
  `${pillBase} ${paymentColors[(status || "").toLowerCase()] || gray}`;

export const promoPillCls = (status?: string) =>
  `${pillBase} ${promoColors[(status || "").toLowerCase()] || gray}`;

// --- react-select brand styling ----------------------------------------------
// Searchable selects (nationality / phone code) inside the booking modals. The
// menu is portalled to <body> with a z-index above the Modal (z 1060) so the
// modal's `overflow-y-auto` body doesn't clip the dropdown.
export type SelectOption = { value: string | number; label: string };

export const bookingSelectStyles: StylesConfig<SelectOption, false> = {
  control: (base, state) => ({
    ...base,
    minHeight: 44,
    borderRadius: 10,
    fontSize: 15,
    backgroundColor: "#fff",
    borderColor: state.isFocused ? "#854ec9" : "#d8d2e1",
    boxShadow: state.isFocused ? "0 0 0 3px rgba(133,78,201,0.15)" : "none",
    ":hover": { borderColor: "#854ec9" },
  }),
  valueContainer: (base) => ({ ...base, padding: "2px 10px" }),
  placeholder: (base) => ({ ...base, color: "#8a8398" }),
  menu: (base) => ({ ...base, borderRadius: 10, overflow: "hidden" }),
  menuPortal: (base) => ({ ...base, zIndex: 100001 }),
  option: (base, state) => ({
    ...base,
    fontSize: 14,
    cursor: "pointer",
    color: state.isSelected ? "#fff" : "#14101c",
    backgroundColor: state.isSelected
      ? "#854ec9"
      : state.isFocused
        ? "#f5f0fc"
        : "#fff",
    ":active": { backgroundColor: "#854ec9", color: "#fff" },
  }),
};
