import priceFormat from "@/helpers/priceFormat";
import Modal from "@/components/tour-detail-page/modal";

export default function PaymentDetailsModal({
  data,
  open,
  onClose,
}: {
  data: any;
  open: boolean;
  onClose: () => void;
}) {
  const fmt = (amount: number) =>
    priceFormat({
      amount,
      currency: data.buyer_currency,
      maximumFractionDigits: 2,
    });

  const thCls =
    "tw-px-3 tw-py-2.5 tw-text-[11px] tw-font-semibold tw-uppercase tw-tracking-wide tw-text-[#6b6577]";
  const tdCls =
    "tw-px-3 tw-py-3 tw-text-[13.5px] tw-text-[#3f3a4d] tw-border-0 tw-border-t tw-border-solid tw-border-[#f0edf5] tw-align-middle";

  return (
    <Modal open={open} onClose={onClose} title="Amount Details" size="lg">
      <div className="tw-font-display tw--mx-1 tw-overflow-x-auto">
        <table className="tw-w-full tw-border-collapse">
          <thead>
            <tr className="tw-bg-[#f7f5fb] tw-text-left">
              <th className={thCls}>Product/Service</th>
              <th className={`${thCls} tw-text-center`}>Price per Person</th>
              <th className={`${thCls} tw-text-center`}>Discount per Person</th>
              <th className={`${thCls} tw-text-center`}>Total Person</th>
              <th className={`${thCls} tw-text-center`}>Total Price</th>
              <th className={`${thCls} tw-text-center`}>Total Discount</th>
            </tr>
          </thead>
          <tbody>
            {data.items.map((item: any) => (
              <tr key={item.id}>
                <td className={tdCls}>
                  <span className="tw-font-semibold tw-text-[#14101c]">
                    {item.item_name}
                  </span>
                  {item.details && (
                    <p className="tw-m-0 tw-mt-0.5 tw-text-[12px] tw-text-[#8a8398]">
                      {item.details}
                    </p>
                  )}
                </td>
                <td className={`${tdCls} tw-text-center`}>
                  {fmt(item.unit_price_buyer)}
                </td>
                <td className={`${tdCls} tw-text-center tw-text-[#b23838]`}>
                  {item.discount_amount_per_unit_buyer > 0 &&
                    `- ${fmt(item.discount_amount_per_unit_buyer)}`}
                </td>
                <td className={`${tdCls} tw-text-center`}>{item.quantity}</td>
                <td className={`${tdCls} tw-text-center`}>
                  {item.unit_price_old_buyer > 0 &&
                    item.unit_price_buyer !== item.unit_price_old_buyer && (
                      <span className="tw-mr-1 tw-text-[12px] tw-text-[#b23838] tw-line-through">
                        {fmt(item.quantity * item.unit_price_old_buyer)}
                      </span>
                    )}
                  {fmt(item.quantity * item.unit_price_buyer)}
                </td>
                <td className={`${tdCls} tw-text-center tw-text-[#b23838]`}>
                  {item.total_discount_amount_buyer > 0 &&
                    `- ${fmt(item.total_discount_amount_buyer)}`}
                </td>
              </tr>
            ))}

            {data.amounts.buyer.original_amount !=
              data.amounts.buyer.final_amount && (
              <tr>
                <td className={`${tdCls} tw-text-right tw-font-semibold tw-text-[#14101c]`} colSpan={4}>
                  Total Amount
                </td>
                <td className={`${tdCls} tw-text-right tw-text-[16px] tw-font-bold tw-text-[#14101c]`}>
                  {fmt(data.amounts.buyer.original_amount)}
                </td>
                <td className={tdCls}></td>
              </tr>
            )}
            {data.amounts.buyer.discount_amount > 0 && (
              <tr>
                <td className={`${tdCls} tw-text-right tw-font-semibold tw-text-[#b23838]`} colSpan={4}>
                  Discount
                </td>
                <td className={`${tdCls} tw-text-right tw-text-[#b23838]`}>
                  - {fmt(data.amounts.buyer.discount_amount)}
                </td>
                <td className={tdCls}></td>
              </tr>
            )}
            {data.amounts.buyer.coupon_amount > 0 && (
              <tr>
                <td className={`${tdCls} tw-text-right tw-font-semibold tw-text-[#b23838]`} colSpan={4}>
                  Promo Code Discount
                </td>
                <td className={`${tdCls} tw-text-right tw-text-[#b23838]`}>
                  - {fmt(data.amounts.buyer.coupon_amount)}
                </td>
                <td className={tdCls}></td>
              </tr>
            )}
            <tr>
              <td className={`${tdCls} tw-text-right tw-font-bold tw-text-[#14101c]`} colSpan={4}>
                Amount to Pay
              </td>
              <td className={`${tdCls} tw-text-right tw-text-[16px] tw-font-bold tw-text-[#854ec9]`}>
                {fmt(data.amounts.buyer.final_amount)}
              </td>
              <td className={tdCls}></td>
            </tr>
          </tbody>
        </table>
      </div>
    </Modal>
  );
}
