import { apiClient, ApiError } from "@/lib/apiClient";

// apiv3 merkezi promosyon kodu uygulama (POST /bookings/{ref}/promo-codes/apply).
// Çağıran bileşen hata.status + hata.response (sunucu gövdesi) okuyor → bu sözleşmeyi koru.
export async function applyPromotion(
  referenceId: string,
  promotionCode: string,
  token: string
) {
  try {
    return await apiClient(`/bookings/${referenceId}/promo-codes/apply`, {
      method: "POST",
      body: { code: promotionCode, token },
    });
  } catch (e) {
    if (e instanceof ApiError) {
      const error: any = new Error("Failed to apply promotion");
      error.status = e.status;
      error.response = e.body ?? {};
      throw error;
    }
    throw e;
  }
}

// Uygulanmış kodu geri alır; tutarlar rezervasyonda yeniden hesaplanır.
export async function removePromotion(referenceId: string, token: string) {
  try {
    return await apiClient(`/bookings/${referenceId}/promo-codes`, {
      method: "DELETE",
      body: { token },
    });
  } catch (e) {
    if (e instanceof ApiError) {
      const error: any = new Error("Failed to remove promotion");
      error.status = e.status;
      error.response = e.body ?? {};
      throw error;
    }
    throw e;
  }
}
