"use client";

import { useState } from "react";
import { applyPromotion, removePromotion } from "@/services/booking/applyPromotion";
import { spinnerCls } from "@/components/tour-detail-page/ui";

type Applied = { code: string; discount: number } | null;

/**
 * Ödeme ekranındaki promosyon kodu kutusu.
 *
 * İndirimi SUNUCU hesaplar; buradan hiçbir fiyat gönderilmez. Başarılı yanıttaki
 * güncel tutarlar `onAmounts` ile üst bileşene verilir — sayfa yenilenmez, ama
 * ödenecek tutar ve depozito satırı anında güncellenir.
 */
export default function PromoCodeBox({
  referenceId,
  token,
  applied,
  currency,
  onAmounts,
}: {
  referenceId: string;
  token: string;
  applied: Applied;
  currency: string;
  onAmounts: (amounts: any, applied: Applied) => void;
}) {
  const [open, setOpen] = useState(false);
  const [code, setCode] = useState("");
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState("");

  const fmt = (v: number) =>
    new Intl.NumberFormat("en-US", { style: "currency", currency: currency || "EUR" }).format(v || 0);

  const handleApply = async () => {
    const value = code.trim();
    if (!value) return;

    setLoading(true);
    setError("");

    try {
      const res = await applyPromotion(referenceId, value, token);
      onAmounts(res.amounts, { code: res.data?.code ?? value, discount: res.data?.discount ?? 0 });
      setCode("");
      setOpen(false);
    } catch (e: any) {
      setError(e.response?.message || e.response?.error || "This code isn't available for this booking.");
    } finally {
      setLoading(false);
    }
  };

  const handleRemove = async () => {
    setLoading(true);
    setError("");

    try {
      const res = await removePromotion(referenceId, token);
      onAmounts(res.amounts, null);
    } catch (e: any) {
      setError(e.response?.message || e.response?.error || "Failed to remove the code.");
    } finally {
      setLoading(false);
    }
  };

  if (applied) {
    return (
      <div className="tw-my-3 tw-flex tw-items-center tw-justify-between tw-gap-3 tw-rounded-[10px] tw-bg-[#eafaf0] tw-px-3 tw-py-2.5">
        <div className="tw-text-[13px] tw-text-[#1f8a4c]">
          <span className="tw-font-mono tw-font-semibold">{applied.code}</span> applied
          {applied.discount > 0 && <> — you save {fmt(applied.discount)}</>}
        </div>
        <button
          type="button"
          onClick={handleRemove}
          disabled={loading}
          className="tw-shrink-0 tw-border-0 tw-bg-transparent tw-text-[12.5px] tw-font-semibold tw-text-[#1f8a4c] tw-underline tw-cursor-pointer disabled:tw-opacity-60"
        >
          {loading ? <span className={spinnerCls} /> : "Remove"}
        </button>
      </div>
    );
  }

  if (!open) {
    return (
      <button
        type="button"
        onClick={() => setOpen(true)}
        className="tw-my-2 tw-border-0 tw-bg-transparent tw-p-0 tw-text-[13px] tw-font-semibold tw-text-[#854ec9] tw-underline tw-cursor-pointer"
      >
        Have a promo code?
      </button>
    );
  }

  return (
    <div className="tw-my-3">
      <div className="tw-flex tw-gap-2">
        <input
          value={code}
          onChange={(e) => setCode(e.target.value.toUpperCase())}
          onKeyDown={(e) => e.key === "Enter" && handleApply()}
          placeholder="Enter code"
          autoFocus
          className="tw-w-full tw-rounded-[8px] tw-border tw-border-solid tw-border-[#e2dded] tw-px-3 tw-py-2 tw-font-mono tw-text-[13.5px] tw-uppercase tw-outline-none focus:tw-border-[#854ec9]"
        />
        <button
          type="button"
          onClick={handleApply}
          disabled={loading || !code.trim()}
          className="tw-min-w-[80px] tw-shrink-0 tw-rounded-[8px] tw-border-0 tw-bg-[#854ec9] tw-px-4 tw-py-2 tw-text-[13px] tw-font-semibold tw-text-white tw-cursor-pointer hover:tw-bg-[#6a3da4] disabled:tw-opacity-60"
        >
          {loading ? <span className={spinnerCls} /> : "Apply"}
        </button>
      </div>

      {error && <p className="tw-mt-2 tw-mb-0 tw-text-[12.5px] tw-text-[#b23838]">{error}</p>}
    </div>
  );
}
